episodes.settled_cypher:
/* accept-cost */
MATCH (d:Medium {_workspace_id: $workspace_id})-[:SIGN_IN]->(a:Account {_workspace_id: $workspace_id})
MATCH (d)-[:SIGN_IN]->(b:Account {_workspace_id: $workspace_id})
WHERE a.acct_no < b.acct_no
AND EXISTS {
    MATCH (a)-[:TRANSFER]-(b)
}
AND EXISTS {
    MATCH (ownerA)-[:OWN]->(a)
    MATCH (ownerB)-[:OWN]->(b)
    WHERE ownerA <> ownerB
      AND (ownerA)-[:GUARANTEE]->(ownerB)
      AND (ownerB)-[:GUARANTEE]->(ownerA)
}
RETURN a.acct_no AS acct1, b.acct_no AS acct2
LIMIT $limit

